SELECT
  (SELECT default_version::text FROM pg_available_extensions WHERE name = 'pg_stat_statements') AS installed_version_offered,
  (SELECT extversion::text FROM pg_extension WHERE extname = 'pg_stat_statements') AS installed_version_actual;

SELECT
  (SELECT COUNT(*) FROM pg_extension) AS pg_extension_total_rows,
  (SELECT COUNT(*) FROM pg_available_extensions) AS pg_available_extensions_total_rows;

